SELECT ar.*, rt.title, rt.content
FROM analysis_result ar
JOIN raw_text rt ON ar.text_id = rt.id


        AND ar.category = #{category}


        AND ar.sentiment = #{sentiment}


ORDER BY ar.analyzed_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM analysis_result ar


        AND ar.category = #{category}


        AND ar.sentiment = #{sentiment}

SELECT ar.*, rt.title, rt.content FROM analysis_result ar JOIN raw_text rt ON ar.text_id = rt.id
AND ar.category = #{category}
AND ar.sentiment = #{sentiment}
ORDER BY ar.analyzed_at DESC LIMIT 5000
